begin;
create function pg_temp.assert_true(ok boolean, message text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAIL: %', message; end if; end $$;
create function pg_temp.expect_error(statement text, expected_state text) returns void language plpgsql as $$
declare failed boolean := false;
begin begin execute statement;
exception when others then
  if sqlstate <> expected_state then raise exception 'Expected %, got %: %', expected_state,sqlstate,sqlerrm; end if;
  failed:=true;
end;
if not failed then raise exception 'FAIL: unexpected success'; end if;
end $$;
insert into auth.users(id) values ('33000000-0000-4000-8000-000000000001'),('33000000-0000-4000-8000-000000000002');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.expect_error($s$select public.submit_demo_claim('23000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Título válido','Descripción de prueba','Dirección 123','Centro')$s$,'42501');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','33000000-0000-4000-8000-000000000001',true);
select public.submit_demo_claim('23000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','  Título válido  ','Descripción de prueba','Dirección 123','Centro');
select public.submit_demo_claim('23000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Título válido','Descripción de prueba','Dirección 123','Centro');
select pg_temp.assert_true((select count(*)=1 from public.claims where author_id=auth.uid()),'idempotent create');
select pg_temp.assert_true((select author_id=auth.uid() and moderation_status='pendiente' and status='publicado' and is_demo and entity_id is null and title='Título válido' from public.claims where id='23000000-0000-4000-8000-000000000001'),'fixed server fields and trim');
select pg_temp.assert_true((select count(*)=0 from public.point_movements),'sending does not award points');
select pg_temp.expect_error($s$select public.submit_demo_claim('23000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Otro título','Descripción de prueba','Dirección 123','Centro')$s$,'22023');
select pg_temp.expect_error($s$select public.submit_demo_claim(gen_random_uuid(),'33000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Título válido','Descripción de prueba','Dirección 123','Centro')$s$,'42501');
select pg_temp.expect_error($s$select public.submit_demo_claim(gen_random_uuid(),auth.uid(),gen_random_uuid(),'Título válido','Descripción de prueba','Dirección 123','Centro')$s$,'23503');
select pg_temp.expect_error($s$select public.submit_demo_claim(gen_random_uuid(),auth.uid(),'10000000-0000-4000-8000-000000000001','       ','Descripción de prueba','Dirección 123','Centro')$s$,'22023');
select pg_temp.expect_error($s$select public.submit_demo_claim(gen_random_uuid(),auth.uid(),'10000000-0000-4000-8000-000000000001',repeat(chr(160),8),'Descripción de prueba','Dirección 123','Centro')$s$,'22023');
select pg_temp.expect_error($s$insert into public.claims(author_id) values ('33000000-0000-4000-8000-000000000002')$s$,'42501');
select pg_temp.expect_error($s$update public.claims set moderation_status='aprobado' where author_id=auth.uid()$s$,'42501');
select pg_temp.expect_error($s$insert into public.claims(category_id,title,description,address,neighborhood,status) values ('10000000-0000-4000-8000-000000000001','Título válido','Descripción de prueba','Dirección 123','Centro','resuelto')$s$,'42501');
select pg_temp.expect_error($s$insert into public.claims(entity_id) values (gen_random_uuid())$s$,'42501');
select pg_temp.expect_error($s$insert into public.point_movements(user_id,amount,reason,event_id) values (auth.uid(),20,'claim_validated',gen_random_uuid())$s$,'42501');
select pg_temp.expect_error($s$select public.attach_own_claim_photo('23000000-0000-4000-8000-000000000001',auth.uid(),'33000000-0000-4000-8000-000000000001/23000000-0000-4000-8000-000000000001/claim/73000000-0000-4000-8000-000000000001.jpg')$s$,'P0002');
insert into storage.objects(bucket_id,name) values ('claim-photos','33000000-0000-4000-8000-000000000001/23000000-0000-4000-8000-000000000001/claim/73000000-0000-4000-8000-000000000001.jpg');
select public.attach_own_claim_photo('23000000-0000-4000-8000-000000000001',auth.uid(),'33000000-0000-4000-8000-000000000001/23000000-0000-4000-8000-000000000001/claim/73000000-0000-4000-8000-000000000001.jpg');
select public.attach_own_claim_photo('23000000-0000-4000-8000-000000000001',auth.uid(),'33000000-0000-4000-8000-000000000001/23000000-0000-4000-8000-000000000001/claim/73000000-0000-4000-8000-000000000001.jpg');
select pg_temp.assert_true((select count(*)=1 from public.claim_attachments where owner_id=auth.uid()),'association retry does not duplicate');
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='claim-photos'),'owner can read associated private photo');
select pg_temp.expect_error($s$select public.attach_own_claim_photo('23000000-0000-4000-8000-000000000001',auth.uid(),'33000000-0000-4000-8000-000000000001/23000000-0000-4000-8000-000000000001/claim/73000000-0000-4000-8000-000000000002.jpg')$s$,'23505');
select set_config('request.jwt.claim.sub','33000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.claims where id='23000000-0000-4000-8000-000000000001'),'other user cannot see pending claim');
select pg_temp.assert_true((select count(*)=0 from public.claim_attachments),'other user cannot read private attachment metadata');
select pg_temp.assert_true((select count(*)=0 from storage.objects),'other user cannot read pending photograph');
select pg_temp.expect_error($s$select public.attach_own_claim_photo('23000000-0000-4000-8000-000000000001',auth.uid(),'33000000-0000-4000-8000-000000000001/23000000-0000-4000-8000-000000000001/claim/73000000-0000-4000-8000-000000000001.jpg')$s$,'42501');
select pg_temp.expect_error($s$select public.submit_demo_claim('23000000-0000-4000-8000-000000000001',auth.uid(),'10000000-0000-4000-8000-000000000001','Título válido','Descripción de prueba','Dirección 123','Centro')$s$,'42501');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select count(*)=9 from public.claims where moderation_status='aprobado'),'public seed unchanged');
select pg_temp.assert_true((select count(*)=0 from public.claims where id='23000000-0000-4000-8000-000000000001'),'pending never public');
select pg_temp.assert_true((select count(*)=0 from storage.objects),'pending photo never public');
reset role;
rollback;
